  async function request(path, options = {}) { const response = await fetch(path, { credentials: 'same-origin', cache: 'no-store', ...options }); const data = await response.json().catch(() => ({})); if (!response.ok) throw Error(data.error || 'Purchase order request failed'); return data; }
