  function renderReceiverOptions() { const select = $('poReceiveOrder'), previous = select.value; select.replaceChildren(); const placeholder = document.createElement('option'); placeholder.value = ''; placeholder.textContent = 'Choose sent PO to receive'; select.append(placeholder); expectedOrders().forEach(order => { const option = document.createElement('option'); option.value = order.id; option.textContent = order.purchase_order_number + ' · ' + (order.vendor_name || 'Supplier') + ' · ' + (order.locations?.name || 'Receiving location'); select.append(option); }); if ([...select.options].some(option => option.value === previous)) select.value = previous; }
