  async function load() { const data = await request('/api/purchase-orders'); orders = data.orders || []; locations = data.locations || []; vendors = data.vendors || []; capabilities = data.capabilities || {}; renderAll(); set(capabilities.canManagePurchaseOrders ? 'PO master ready. Click an order to work it.' : 'Choose a sent PO from Overview to begin scan-first receiving.'); }
