  function quickAddProduct(product) { const cost = Number(product.moving_average_cost || product.purchase_price || 0); const existing = draftLines.find(line => Number(line.productId) === Number(product.id)); if (existing) existing.quantity += 1; else draftLines.push({ productId:Number(product.id), sku:product.sku, name:product.name, variantTitle:product.variant_title || '', quantity:1, unitCost:cost, uom:'EA', movingAverageCost:Number(product.moving_average_cost || 0), purchasePrice:Number(product.purchase_price || 0) }); selectedProduct=null; $('poProductSearch').value=''; $('poLineMac').value=''; $('poLineCost').value='0.00'; renderSuggestions([]); renderDraft(); setTimeout(()=>document.querySelector('#poDraftLineRows .line-quantity-input:last-of-type')?.focus(),0); }
