  async function searchProducts() { const term = $('poProductSearch').value.trim(); selectedProduct = null; if (term.length < 2) return renderSuggestions([]); const data = await request('/api/purchase-orders?productSearch=' + encodeURIComponent(term)); renderSuggestions(data.products || []); }
  function addDraftLine() { const quantity = Number($('poLineQuantity').value), unitCost = Number($('poLineCost').value), uom = String($('poLineUom').value || 'EA').trim().toUpperCase(); if (!editable()) throw Error('Only an admin can edit this purchase order.'); if (!selectedProduct || !Number.isFinite(quantity) || quantity <= 0 || !Number.isFinite(unitCost) || unitCost < 0 || !uom) throw Error('Choose a product, positive quantity, UOM, and non-negative unit cost.'); const existing = draftLines.find(line => Number(line.productId) === Number(selectedProduct.id)); if (existing) { existing.quantity += quantity; existing.unitCost = unitCost; existing.uom = uom; } else draftLines.push({ productId: Number(selectedProduct.id), sku: selectedProduct.sku, name: selectedProduct.name, variantTitle: selectedProduct.variant_title || '', quantity, unitCost, uom, movingAverageCost: Number(selectedProduct.moving_average_cost || 0), purchasePrice: Number(selectedProduct.purchase_price || 0) }); selectedProduct = null; $('poProductSearch').value = ''; $('poLineMac').value = ''; $('poLineQuantity').value = '1'; $('poLineUom').value = 'EA'; $('poLineCost').value = '0.00'; renderSuggestions([]); renderDraft(); }
