  $('purchaseOrdersNav').addEventListener('click', () => { document.querySelectorAll('main > section, #overviewView').forEach(element => { if (element.id !== 'purchaseOrdersView') element.hidden = true; }); view.hidden = false; document.querySelectorAll('.nav-item').forEach(item => item.classList.toggle('active', item.id === 'purchaseOrdersNav')); load().catch(error => set(error.message, true)); }); document.querySelectorAll('.nav-item').forEach(item => { if (item.id !== 'purchaseOrdersNav') item.addEventListener('click', () => { view.hidden = true; }); });
  $('purchaseOrdersRefresh').onclick = () => load().catch(error => set(error.message, true)); $('poNewOrder').onclick = () => { if (!capabilities.canManagePurchaseOrders) return set('Only an admin can create a purchase order.', true); openDetail(); }; $('poBackToMaster').onclick = backToMaster; $('poEdit').onclick = () => { editingOrder = true; renderEditor(); }; $('poSave').onclick = () => saveDraft().catch(error => set(error.message, true)); $('poSaveDraft').onclick = () => saveDraft().catch(error => set(error.message, true)); $('poSend').onclick = () => sendOrder().catch(error => set(error.message, true)); $('poDelete').onclick = () => deleteOrder().catch(error => set(error.message, true)); $('poPrint').onclick = () => { try { printPurchaseOrder(); } catch (error) { set(error.message, true); } }; $('poPrintLabels').onclick = () => { try { printZebraLabels(selectedOrder()); } catch (error) { set(error.message, true); } }; $('poReceiveFromDetail').onclick = () => openReceiver(selectedOrder()).catch(error => set(error.message, true)); $('poMasterSearch').oninput = renderMaster; ['poSupplierFilter','poStatusFilter','poSort'].forEach(id => $(id).onchange = renderMaster);
